-- Matview: dune.paltalabs.result_scf_xoxno_swap_activity   cron: 0 5 * * *
-- Última ejecución: 01M5K78NB2S4KEERHQ5ZFHG26N
-- Costo: 2.859 cr; filas: 1303; engine medium
-- Generated by scripts/activity_sql.py. Normalized activity, docs/modelo-de-datos.md.
-- live: one row per user action plus one metadata row with the covered range.
WITH src AS (
WITH ops AS (
  SELECT o.contract_id, o.closed_at, o.transaction_id,
         regexp_extract_all(o.parameters_json_decoded, '"address":"CCVENFSVCBYDHVOACFZXMNNYVOZ3LKXPZYU5LUI4N7KTXOKRVYD7F3TR"\},\{"symbol":"execute_strategy"\},(?:\{"vec":\[)?\{"address":"([GC][A-Z2-7]{55})"', 1) AS senders
  FROM stellar.history_operations o
  WHERE o.closed_at_date >= CURRENT_DATE - INTERVAL '75' DAY AND o.closed_at_date >= (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_swap_activity_archive WHERE row_kind = 'metadata') AND o.closed_at_date < CURRENT_DATE
    AND o.type_string = 'invoke_host_function'
    AND strpos(o.parameters_json_decoded, 'CCVENFSVCBYDHVOACFZXMNNYVOZ3LKXPZYU5LUI4N7KTXOKRVYD7F3TR') > 0
),
tx AS (
  SELECT id, lower(to_hex(transaction_hash)) AS tx_hash
  FROM stellar.history_transactions
  WHERE closed_at_date >= CURRENT_DATE - INTERVAL '75' DAY AND closed_at_date >= (SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_swap_activity_archive WHERE row_kind = 'metadata') AND closed_at_date < CURRENT_DATE AND successful = TRUE
)
SELECT 'xoxno_swap' AS protocol, o.contract_id, o.closed_at, t.tx_hash, s.sender AS user_address,
  CASE WHEN o.contract_id = 'CCVENFSVCBYDHVOACFZXMNNYVOZ3LKXPZYU5LUI4N7KTXOKRVYD7F3TR' THEN 'aggregator_swap' ELSE 'aggregator_nested_swap' END AS action,
  'aggregator_user' AS role, CAST(NULL AS VARCHAR) AS pool,
  CAST(NULL AS VARCHAR) AS token_a, CAST(NULL AS DECIMAL(38,7)) AS amount_a,
  CAST(NULL AS VARCHAR) AS token_b, CAST(NULL AS DECIMAL(38,7)) AS amount_b
FROM ops o
JOIN tx t ON t.id = o.transaction_id
CROSS JOIN UNNEST(o.senders) AS s(sender)
)
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, role, pool, token_a, amount_a, token_b, amount_b,
       'activity' AS row_kind, GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_swap_activity_archive WHERE row_kind = 'metadata'), CAST(CURRENT_DATE - INTERVAL '75' DAY AS DATE)) AS covered_from, CURRENT_DATE AS covered_until,
       CURRENT_TIMESTAMP AS refreshed_at, 'live' AS source_layer
FROM src
WHERE regexp_like(user_address, '^[GC][A-Z2-7]{55}$') AND role IS NOT NULL
UNION ALL
SELECT 'xoxno_swap', NULL, CAST(NULL AS TIMESTAMP WITH TIME ZONE), NULL, NULL, NULL, NULL, NULL, NULL, CAST(NULL AS DECIMAL(38,7)), NULL, CAST(NULL AS DECIMAL(38,7)),
       'metadata', GREATEST((SELECT MAX(covered_until) FROM dune.paltalabs.result_scf_xoxno_swap_activity_archive WHERE row_kind = 'metadata'), CAST(CURRENT_DATE - INTERVAL '75' DAY AS DATE)), CURRENT_DATE, CURRENT_TIMESTAMP, 'live'
